package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.gcd method.
 * Aiming for high branch and line coverage.
 */
public class MathUtils_gcd_TriageGen1Test {

    @Test
    public void testGcdWithZero() {
        // Covers the if ((u == 0) || (v == 0)) branch
        assertEquals(5, MathUtils.gcd(0, 5));
        assertEquals(5, MathUtils.gcd(5, 0));
        assertEquals(0, MathUtils.gcd(0, 0));
        assertEquals(5, MathUtils.gcd(0, -5));
        assertEquals(5, MathUtils.gcd(-5, 0));
    }

    @Test
    public void testGcdBasicPositive() {
        // Covers standard binary GCD logic
        assertEquals(1, MathUtils.gcd(1, 1));
        assertEquals(1, MathUtils.gcd(7, 13));
        assertEquals(6, MathUtils.gcd(12, 18));
        assertEquals(10, MathUtils.gcd(20, 30));
        assertEquals(1, MathUtils.gcd(100, 101));
    }

    @Test
    public void testGcdWithNegativeNumbers() {
        // Covers the logic that makes u and v negative
        assertEquals(6, MathUtils.gcd(-12, 18));
        assertEquals(6, MathUtils.gcd(12, -18));
        assertEquals(6, MathUtils.gcd(-12, -18));
    }

    @Test
    public void testGcdWithPowersOfTwo() {
        // Covers the k (B1. Find power of 2) logic
        assertEquals(8, MathUtils.gcd(16, 24)); // k=3, u=2, v=3 (after division)
        assertEquals(4, MathUtils.gcd(4, 8));
        assertEquals(2, MathUtils.gcd(2, 10));
    }

    @Test
    public void testGcdOddAndEven() {
        // Covers the ternary operator t = ((u & 1) == 1) ? v : -(u / 2)
        // If u is odd: t = v
        assertEquals(1, MathUtils.gcd(3, 4)); 
        // If u is even: t = -(u/2)
        assertEquals(2, MathUtils.gcd(4, 6));
    }

    @Test
    public void testGcdLoopLogic() {
        // Covers the do-while loop and the B5/B6 logic
        // u and v updates based on t being positive or negative
        assertEquals(1, MathUtils.gcd(15, 25));
        assertEquals(7, MathUtils.gcd(49, 77));
    }

    @Test(expected = RuntimeException.class)
    public void testGcdOverflow() {
        // To trigger k == 31, we need both numbers to be multiples of 2^31.
        // However, in Java, int is 32-bit signed. 
        // The only way to have k=31 is if u and v are 0 (handled) or 
        // if we could represent 2^31. Since max int is 2^31-1, 
        // we attempt to trigger the logic via a specific case if possible, 
        // but mathematically, for non-zero ints, k < 31.
        // If the code allows k=31, it would require values that overflowed 
        // or specific edge cases in the implementation's bitwise logic.
        // Since we cannot pass 2^31 as a signed int, we test the logic path if possible.
        // In most standard JVMs, a loop k < 31 prevents this unless u/v are 0.
        // But we attempt to reach it if the implementation allows.
        // Given the constraint of 'int', we assume this is a safety check.

        // Note: In a standard 32-bit signed environment, k reaching 31 
        // with non-zero numbers is impossible because 2^31 overflows to Integer.MIN_VALUE.
        // If u = Integer.MIN_VALUE (-2147483648), (u & 1) == 0.
        // If v = Integer.MIN_VALUE, then k will count up.
        MathUtils.gcd(Integer.MIN_VALUE, Integer.MIN_VALUE);
    }

    @Test
    public void testGcdLargeValues() {
        // Test with large primes or large numbers near Integer.MAX_VALUE
        assertEquals(1, MathUtils.gcd(Integer.MAX_VALUE, Integer.MAX_VALUE - 2));
        assertEquals(1, MathUtils.gcd(1073741823, 1073741821));
    }
}
